const SETTINGS_LINK_FIELDS = [
  { inputId: "systemFreeLink", modalId: "dbSettingsFreeLink", key: "freeLink" },
  { inputId: "systemStreamerLink", modalId: "dbSettingsStreamerLink", key: "streamerLink" },
  { inputId: "systemSniperLink", modalId: "dbSettingsSniperLink", key: "sniperLink" },
  { inputId: "systemSpecialLink", modalId: "dbSettingsSpecialLink", key: "specialLink" },
  { inputId: "systemAimbotLink", modalId: "dbSettingsAimbotLink", key: "aimbotLink" },
  { inputId: "systemPremiumLink", modalId: "dbSettingsPremiumLink", key: "premiumLink" },
  { inputId: "systemCustomisedLink", modalId: "dbSettingsCustomisedLink", key: "customisedLink" }
];
const DB_ENDPOINTS = {
  users: "/api/admin/users",
  keys: "/api/admin/keys",
  admins: "/api/admin/manage/admins",
  orders: "/api/admin/orders/all",
  settings: "/api/admin/settings/all",
  freeSettings: "/api/admin/settings/all", // ?? Naya option yahan add hua
  freeusers: "/api/admin/free-users",
  panelUpdates: "/api/admin/panel-updates" // ?? Naya option yahan add hua
};
const USER_COLUMN_ORDER = ["id", "Id", "username", "Username", "plan", "Plan", "keyValue", "KeyValue", "hwid", "HWID", "isBanned", "IsBanned", "failedLoginAttempts", "FailedLoginAttempts", "lockoutEnd", "LockoutEnd", "expiryTime", "ExpiryTime", "registrationTime", "RegistrationTime", "lastLoginTime", "LastLoginTime"];
const FREE_USER_COLUMN_ORDER = ["id", "Id", "username", "Username", "hwid", "HWID", "CaptchaToken", "CaptchaToken", "isBanned", "IsBanned", "failedLoginAttempts", "FailedLoginAttempts", "lockoutEnd", "LockoutEnd", "firstLoginTime", "FirstLoginTime", "lastLoginTime", "LastLoginTime"];

let cachedSettingsRecord = null;
let currentDbTable = "users";
let currentEditRecordId = 0;
let currentPage = 1;
let searchQuery = "";
let globalDbData = [];
const rowsPerPage = 15;

export function updateMaintenanceButtonUI(isOn) {
  const button = document.getElementById("maintenanceToggleBtn");
  if (!button) return;

  button.dataset.enabled = isOn ? "true" : "false";
  button.classList.remove("btn-maint-on", "btn-maint-off", "btn-neutral");
  button.classList.add(isOn ? "btn-maint-on" : "btn-maint-off");
  button.textContent = isOn ? "Maintenance: ON" : "Maintenance: OFF";
}

export function buildSettingsPayload(overrides) {}

export function populateSystemControlsForm(settings) {
  cachedSettingsRecord = settings || {};

  // populateSystemControlsForm() ke andar:
  const fUserInput = document.getElementById("systemFreeUser");
  const fPassInput = document.getElementById("systemFreePass");
  if (fUserInput) fUserInput.value = String(readObjectValue(settings, ["freeUsername", "FreeUsername"], ""));
  if (fPassInput) fPassInput.value = String(readObjectValue(settings, ["freePassword", "FreePassword"], ""));


  const maxFreeSlotsInput = document.getElementById("systemMaxFreeSlots");
  const latestVersionInput = document.getElementById("systemLatestVersion");
  const updateUrlInput = document.getElementById("systemUpdateUrl");
  const maintenanceReasonInput = document.getElementById("systemMaintenanceReason");

  if (maxFreeSlotsInput) maxFreeSlotsInput.value = String(readObjectValue(settings, ["maxFreeSlots", "MaxFreeSlots"], 20));
  if (latestVersionInput) latestVersionInput.value = String(readObjectValue(settings, ["latestVersion", "LatestVersion"], "1.0"));
  if (updateUrlInput) updateUrlInput.value = String(readObjectValue(settings, ["updateUrl", "UpdateUrl"], ""));
  if (maintenanceReasonInput) maintenanceReasonInput.value = String(readObjectValue(settings, ["maintenanceReason", "MaintenanceReason"], ""));

  SETTINGS_LINK_FIELDS.forEach((field) => {
    const input = document.getElementById(field.inputId);
    if (input) input.value = String(readObjectValue(settings, [field.key, field.key.charAt(0).toUpperCase() + field.key.slice(1)], ""));
  });

  updateMaintenanceButtonUI(Boolean(readObjectValue(settings, ["isMaintenanceMode", "IsMaintenanceMode"], false)));
}

export async function loadSystemControls() {
  try {
    const result = await Core.requestJson("/api/admin/settings/all", {
      method: "GET",
      headers: Core.getAuthHeader(),
      retries: 0
    });

    if (Core.handleAdminAuthFailure(result.status)) return;
    if (!result.ok) {
      Core.showMessage(Core.extractErrorMessage(result.data, "Failed to load system settings."), "error");
      return;
    }

    populateSystemControlsForm(getSettingsRecord(result.data));
  } catch (err) {
    Core.showMessage("Failed to load system controls.", "error");
  }
}

export async function saveSystemControls() {
  const payload = buildSettingsPayload({

    maxFreeSlots: document.getElementById("systemMaxFreeSlots")?.value,
    latestVersion: document.getElementById("systemLatestVersion")?.value,
    updateUrl: document.getElementById("systemUpdateUrl")?.value,
    maintenanceReason: document.getElementById("systemMaintenanceReason")?.value,
    isMaintenanceMode: document.getElementById("maintenanceToggleBtn")?.dataset.enabled === "true"
  });
  // buildSettingsPayload() ke andar:
  payload.freeUsername = String(document.getElementById("systemFreeUser")?.value || "").trim();
  payload.freePassword = String(document.getElementById("systemFreePass")?.value || "").trim();

  SETTINGS_LINK_FIELDS.forEach((field) => {
    payload[field.key] = String(document.getElementById(field.inputId)?.value || "").trim();
  });

  Core.showLoader("Saving system controls...");

  try {
    const result = await Core.requestJson("/api/admin/settings/update", {
      method: "PUT",
      headers: Core.getAuthHeader(),
      body: payload
    });

    Core.hideLoader();
    if (Core.handleAdminAuthFailure(result.status)) return;
    if (!result.ok) {
      Core.showMessage(Core.extractErrorMessage(result.data, "Failed to update system controls."), "error");
      return;
    }

    cachedSettingsRecord = { ...cachedSettingsRecord, ...payload };
    populateSystemControlsForm(cachedSettingsRecord);
    if (currentDbTable === "settings") await loadDbData();
    Core.showMessage("System controls updated successfully.", "success");
  } catch (err) {
    Core.hideLoader();
    Core.showMessage("Server error while updating system controls.", "error");
  }
}

export async function toggleMaintenanceMode() {
  const button = document.getElementById("maintenanceToggleBtn");
  const nextValue = button?.dataset.enabled !== "true";

  Core.showLoader(nextValue ? "Enabling maintenance..." : "Disabling maintenance...");

  try {
    const result = await Core.requestJson("/api/admin/maintenance/toggle", {
      method: "POST",
      headers: Core.getAuthHeader(),
      // 🔥 FIX: Backend ko dono formats bhej rahe hain taaki koi parsing fail na ho
      body: { isMaintenanceMode: nextValue, IsMaintenanceMode: nextValue }
    });

    Core.hideLoader();
    if (Core.handleAdminAuthFailure(result.status)) return;
    if (!result.ok) {
      Core.showMessage(Core.extractErrorMessage(result.data, "Failed to update maintenance mode."), "error");
      return;
    }

    // 🔥 FIX: Response se sahi value uthayi ja rahi hai
    const isMaintNow = Boolean(result.data.isMaintenanceMode || result.data.IsMaintenanceMode);

    cachedSettingsRecord = {
      ...(cachedSettingsRecord || {}),
      isMaintenanceMode: isMaintNow,
      IsMaintenanceMode: isMaintNow
    };

    updateMaintenanceButtonUI(isMaintNow);
    if (currentDbTable === "settings") await loadDbData();
    Core.showMessage(result.data.message || "Maintenance status updated.", "success");
  } catch (err) {
    Core.hideLoader();
    Core.showMessage("Server error while toggling maintenance mode.", "error");
  }
}

export function sortKeysForTable(keys) {
  const sorted = [...keys];

  if (currentDbTable === "users") {
    sorted.sort((left, right) => {
      const leftIndex = USER_COLUMN_ORDER.indexOf(left);
      const rightIndex = USER_COLUMN_ORDER.indexOf(right);
      return (leftIndex === -1 ? 999 : leftIndex) - (rightIndex === -1 ? 999 : rightIndex);
    });
  }

  if (currentDbTable === "freeusers") {
    sorted.sort((left, right) => {
      const leftIndex = FREE_USER_COLUMN_ORDER.indexOf(left);
      const rightIndex = FREE_USER_COLUMN_ORDER.indexOf(right);
      return (leftIndex === -1 ? 999 : leftIndex) - (rightIndex === -1 ? 999 : rightIndex);
    });
  }

  return sorted;
}

export function bindBulkDeleteLogic() {
  const selectAllCheckbox = document.getElementById("selectAllCheckbox");
  const bulkDeleteBtn = document.getElementById("bulkDeleteBtn");

  if (selectAllCheckbox) {
    selectAllCheckbox.addEventListener("change", (event) => {
      document.querySelectorAll(".row-checkbox").forEach((checkbox) => {
        checkbox.checked = event.target.checked;
      });
      updateBulkDeleteState();
    });
  }

  document.querySelectorAll(".row-checkbox").forEach((checkbox) => {
    checkbox.addEventListener("change", updateBulkDeleteState);
  });

  if (bulkDeleteBtn) {
    bulkDeleteBtn.onclick = () => {
      const ids = Array.from(document.querySelectorAll(".row-checkbox:checked"))
        .map((checkbox) => checkbox.getAttribute("data-id"))
        .filter(Boolean);

      if (ids.length === 0) return;

      openDeleteConfirmation(`${ids.length} record(s) from ${currentDbTable.toUpperCase()}`, async () => {
        Core.showLoader(`Deleting ${ids.length} record(s)...`);

        try {
          const requests = ids.map((id) => {
            const endpointMap = {
              users: `/api/admin/user/delete/${id}`,
              keys: `/api/admin/manage/key/delete/${id}`,
              admins: `/api/admin/manage/admin/delete/${id}`,
              orders: `/api/admin/orders/delete/${id}`,
              freeusers: `/api/admin/manage/free-user/delete/${id}`
            };

            return Core.requestJson(endpointMap[currentDbTable], {
              method: "DELETE",
              headers: Core.getAuthHeader()
            });
          });

          const results = await Promise.all(requests);
          const failedCount = results.filter((item) => !item.ok).length;
          Core.hideLoader();

          if (failedCount > 0) {
            Core.showMessage(`${failedCount} record(s) failed to delete.`, "error");
          } else {
            Core.showMessage(`Deleted ${ids.length} record(s) successfully.`, "success");
          }

          await loadDbData();
        } catch (err) {
          Core.hideLoader();
          Core.showMessage("Server error while deleting records.", "error");
        }
      });
    };
  }

  updateBulkDeleteState();
}

export function updateBulkDeleteState() {
  const checkedRows = document.querySelectorAll(".row-checkbox:checked").length;
  const bulkDeleteBtn = document.getElementById("bulkDeleteBtn");
  const bulkDeleteCount = document.getElementById("bulkDeleteCount");
  const selectAllCheckbox = document.getElementById("selectAllCheckbox");

  if (bulkDeleteCount) bulkDeleteCount.textContent = String(checkedRows);
  toggleControlVisibility(bulkDeleteBtn, checkedRows > 0);

  if (selectAllCheckbox && checkedRows === 0) {
    selectAllCheckbox.checked = false;
  }
}

export function renderDbTable(data) {
  const head = document.getElementById("dbTableHead");
  const body = document.getElementById("dbTableBody");
  if (!head || !body) return;

  head.innerHTML = "";
  body.innerHTML = "";

  const safeData = (data || []).filter((row) => row !== null && row !== undefined);
  if (safeData.length === 0) {
    const headerRow = document.createElement("tr");
    headerRow.appendChild(document.createElement("th")).textContent = "Status";
    head.appendChild(headerRow);

    const bodyRow = document.createElement("tr");
    const bodyCell = document.createElement("td");
    bodyCell.className = "text-center text-warning";
    bodyCell.textContent = "No records found in database.";
    bodyRow.appendChild(bodyCell);
    body.appendChild(bodyRow);
    return;
  }

  const uniqueKeys = new Set();
  safeData.forEach((row) => Object.keys(row).forEach((key) => uniqueKeys.add(key)));
  const keys = sortKeysForTable(Array.from(uniqueKeys));

  const headerRow = document.createElement("tr");
  if (currentDbTable !== "settings") {
    const checkboxHeader = document.createElement("th");
    checkboxHeader.className = "text-center";
    checkboxHeader.style.width = "40px";

    const selectAllCheckbox = document.createElement("input");
    selectAllCheckbox.type = "checkbox";
    selectAllCheckbox.id = "selectAllCheckbox";
    selectAllCheckbox.className = "scale-checkbox";
    checkboxHeader.appendChild(selectAllCheckbox);
    headerRow.appendChild(checkboxHeader);
  }

  keys.forEach((key) => {
    const th = document.createElement("th");
    th.textContent = key.toUpperCase();
    headerRow.appendChild(th);
  });

  const actionHeader = document.createElement("th");
  actionHeader.textContent = "ACTIONS";
  headerRow.appendChild(actionHeader);
  head.appendChild(headerRow);

  safeData.forEach((rowData) => {
    const row = document.createElement("tr");

    if (currentDbTable !== "settings") {
      const checkCell = document.createElement("td");
      checkCell.className = "text-center";

      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.className = "row-checkbox scale-checkbox";
      checkbox.setAttribute("data-id", String(readObjectValue(rowData, ["id", "Id"], "")));
      checkCell.appendChild(checkbox);
      row.appendChild(checkCell);
    }

    keys.forEach((key) => {
      const cell = document.createElement("td");
      const value = rowData[key];

      if (value === true) cell.appendChild(createBadge("True", "good"));
      else if (value === false) cell.appendChild(createBadge("False", "bad"));
      else if (String(key).toLowerCase() === "status") {
        // 🔥 NAYA LOGIC: Status Color Badges (Using existing classes)
        const statusStr = String(value).toLowerCase();
        if (statusStr === "approved") cell.appendChild(createBadge("Approved", "good"));
        else if (statusStr === "pending") cell.appendChild(createBadge("Pending", "warning")); // Note: "warning" might use text-warning color if no specific badge exists, or fallback to default
        else if (statusStr === "rejected") cell.appendChild(createBadge("Rejected", "bad"));
        else cell.textContent = value;
      }
      else if (String(key).toLowerCase().includes("time") && value) cell.textContent = new Date(value).toLocaleString();
      else cell.textContent = value === null || value === undefined || value === "" ? "-" : String(value);

      row.appendChild(cell);
    });

    const actionCell = document.createElement("td");
    const editBtn = document.createElement("button");
    editBtn.type = "button";
    editBtn.className = "btn-danger";
    editBtn.textContent = "Edit / Manage";
    editBtn.addEventListener("click", () => openOwnerEditModal(rowData));
    actionCell.appendChild(editBtn);
    row.appendChild(actionCell);

    body.appendChild(row);
  });

  bindBulkDeleteLogic();
}

export function applyFilterAndPagination() {
  let filteredData = globalDbData;

  if (searchQuery.trim()) {
    const query = searchQuery.trim().toLowerCase();
    filteredData = globalDbData.filter((row) => {
      return Object.values(row).some((value) => String(value).toLowerCase().includes(query));
    });
  }

  const totalRows = filteredData.length;
  const totalPages = Math.max(1, Math.ceil(totalRows / rowsPerPage));
  if (currentPage > totalPages) currentPage = totalPages;
  if (currentPage < 1) currentPage = 1;

  const startIndex = (currentPage - 1) * rowsPerPage;
  const pageData = filteredData.slice(startIndex, startIndex + rowsPerPage);
  const pageInfoText = document.getElementById("pageInfoText");
  const prevPageBtn = document.getElementById("prevPageBtn");
  const nextPageBtn = document.getElementById("nextPageBtn");

  if (pageInfoText) pageInfoText.textContent = `Page ${currentPage} of ${totalPages} (${totalRows} Total)`;
  if (prevPageBtn) prevPageBtn.disabled = currentPage === 1;
  if (nextPageBtn) nextPageBtn.disabled = currentPage === totalPages;

  renderDbTable(pageData);
}

export async function loadDbData() {
  const endpoint = DB_ENDPOINTS[currentDbTable] || DB_ENDPOINTS.users;
  const body = document.getElementById("dbTableBody");
  const head = document.getElementById("dbTableHead");

  Core.showLoader(`Fetching ${currentDbTable.toUpperCase()} data...`);

  try {
    const result = await Core.requestJson(endpoint, {
      method: "GET",
      headers: Core.getAuthHeader()
    });

    Core.hideLoader();
    if (Core.handleAdminAuthFailure(result.status)) return;

    if (!result.ok) {
      if (head) head.innerHTML = "<tr><th>ERROR STATUS</th></tr>";
      if (body) body.innerHTML = `<tr><td class="text-center title-danger">API returned status ${result.status}.</td></tr>`;
      Core.showMessage(Core.extractErrorMessage(result.data, "Failed to load database data."), "error");
      return;
    }

  let records = [];
    if (currentDbTable === "settings" || currentDbTable === "freeSettings") {
      // Backend dono table ka merged data bhejta hai, hum yahan usko split kar rahe hain
      const mergedData = getSettingsRecord(result.data);
      cachedSettingsRecord = mergedData;
      populateSystemControlsForm(cachedSettingsRecord);
      
      if (currentDbTable === "settings") {
          records = [{
              id: mergedData.id || 1,
              isMaintenanceMode: mergedData.isMaintenanceMode ?? mergedData.IsMaintenanceMode,
              latestVersion: mergedData.latestVersion || mergedData.LatestVersion,
              updateUrl: mergedData.updateUrl || mergedData.UpdateUrl,
              maintenanceReason: mergedData.maintenanceReason || mergedData.MaintenanceReason,
              
              // 🔥 FIX: Saari links yahan add kar di hain taaki purani links show hon aur save hon!
              freeLink: mergedData.freeLink || mergedData.FreeLink || "",
              streamerLink: mergedData.streamerLink || mergedData.StreamerLink || "",
              sniperLink: mergedData.sniperLink || mergedData.SniperLink || "",
              specialLink: mergedData.specialLink || mergedData.SpecialLink || "",
              aimbotLink: mergedData.aimbotLink || mergedData.AimbotLink || "",
              premiumLink: mergedData.premiumLink || mergedData.PremiumLink || "",
              customisedLink: mergedData.customisedLink || mergedData.CustomisedLink || ""
          }];
      } else {
          records = [{
              id: mergedData.id || 1,
              freeUsername: mergedData.freeUsername || mergedData.FreeUsername || "",
              freePassword: mergedData.freePassword || mergedData.FreePassword || "",
              freeValidDays: mergedData.freeValidDays || mergedData.FreeValidDays || 30,
              maxFreeSlots: mergedData.maxFreeSlots || mergedData.MaxFreeSlots || 20,
              showHomeDownloadBtn: mergedData.showHomeDownloadBtn ?? mergedData.ShowHomeDownloadBtn ?? false
          }];
      }
    } else if (Array.isArray(result.data)) {
      records = result.data;
    } else if (result.data && typeof result.data === "object") {
      const arrayPayload = Core.normalizeListPayload(result.data, ["users", "Users", "keys", "Keys", "admins", "Admins", "orders", "Orders", "freeUsers", "FreeUsers", "freeusers"]);
      records = arrayPayload.length > 0 ? arrayPayload : [result.data];
    }

    globalDbData = records;
    currentPage = 1;
    applyFilterAndPagination();
  } catch (err) {
    Core.hideLoader();
    if (head) head.innerHTML = "<tr><th>ERROR STATUS</th></tr>";
    if (body) body.innerHTML = '<tr><td class="text-center title-danger">Server disconnected. Check backend connectivity.</td></tr>';
  }
}

export function getSettingsModalMarkup(settingsRow) {
  const markup = [
    `<div class="input-group"><label for="dbSettingsMaxFree">Max Free Panel Slots</label><input id="dbSettingsMaxFree" type="number" value="${Core.escapeHTML(readObjectValue(settingsRow, ["maxFreeSlots", "MaxFreeSlots"], 20))}"></div>`,
    `<div class="input-group"><label for="dbSettingsVersion">Latest Panel Version</label><input id="dbSettingsVersion" type="text" value="${Core.escapeHTML(readObjectValue(settingsRow, ["latestVersion", "LatestVersion"], "1.0"))}"></div>`,
    `<div class="input-group"><label for="dbSettingsUrl">Update Download Link</label><input id="dbSettingsUrl" type="url" placeholder="https://..." value="${Core.escapeHTML(readObjectValue(settingsRow, ["updateUrl", "UpdateUrl"], ""))}"></div>`,
    `<div class="input-group"><label for="dbSettingsMaintenance">Maintenance Status</label><select id="dbSettingsMaintenance"><option value="true" ${readObjectValue(settingsRow, ["isMaintenanceMode", "IsMaintenanceMode"], false) ? "selected" : ""}>ON (Block Users)</option><option value="false" ${!readObjectValue(settingsRow, ["isMaintenanceMode", "IsMaintenanceMode"], false) ? "selected" : ""}>OFF (Live)</option></select></div>`,
    `<div class="input-group"><label for="dbSettingsReason">Custom Maintenance Reason</label><textarea id="dbSettingsReason" rows="2" style="width:100%; border-radius:8px; padding:8px;">${Core.escapeHTML(readObjectValue(settingsRow, ["maintenanceReason", "MaintenanceReason"], ""))}</textarea></div>`
  ];

  SETTINGS_LINK_FIELDS.forEach((field) => {
    const label = field.key
      .replace(/([A-Z])/g, " $1")
      .replace(/^./, (char) => char.toUpperCase())
      .replace("Customised", "Customised");
    markup.push(`<div class="input-group"><label for="${field.modalId}">${Core.escapeHTML(label)}</label><input id="${field.modalId}" type="url" placeholder="https://..." value="${Core.escapeHTML(readObjectValue(settingsRow, [field.key, field.key.charAt(0).toUpperCase() + field.key.slice(1)], ""))}"></div>`);
  });

  return markup.join("");
}

